Definition fr1_XS {HCEIL : HeapCeil} (H : asr) (ff fp : Z) : list (Z * Z) := [(as_FSB H, as_FSB H + AFS_FLAGS); (fp, fp + 1); (ff, ff + 128); (sh ff, sh ff + 16)]%Z.

Section HCW.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.

Lemma fr1_XS_scratch : forall LF ff fp, fresh_frame H LF 1 ff fp -> Forall (fs_scratch H LF) (fr1_XS H ff fp).
Proof.
  intros LF ff fp FF. pose proof (fs_scratch_of_fresh H _ _ _ _ FF) as FX. unfold fr1_XS.
  rewrite fsz_1, fshn_1 in FX. exact FX.
Qed.

(* [comment removed for export] *)
Lemma AScheduler_keep : forall (s : as_St H) LB LF mh mr (W XS : list (Z * Z)) m m' S Sv,
  as_RHEAP H s LB mh -> as_RFS H LF mr -> Forall (fs_scratch H LF) XS ->
  Forall noshadow W -> Forall (fun iv : Z * Z => S + NEWSZ_SCH <= fst iv \/ snd iv <= S) W ->
  AScheduler LB m S Sv -> munch (W ++ XS) m m' -> wmono asegs m m' -> AScheduler LB m' S Sv.
Proof.
  intros s LB LF mh mr W XS m m' S Sv HP RF FX NS OFF SCH MU WM.
  assert (XP : xpres H LB (2^64) (W ++ XS) m m').
  { eapply xpres_of_munch with (s := s) (m0 := mh); [exact HH| exact HP| exact MU| exact WM|].
    eapply Forall_impl; [| exact (Forall_rin_self (W ++ XS))]. intros iv K. right. exact K. }
  eapply (AScheduler_xpres_app_scratch H HH); [exact HP| exact RF| exact NS| exact FX| exact OFF| exact SCH| exact XP].
Qed.
